<?php
// Local-only test: synthetic identities; never import a real teacher workbook here.
if(getenv('DGS_TEST_ALLOW_FIXTURES')!=='1'||empty($argv[1]))exit(2);
require $argv[1];wp_set_current_user(get_user_by('login','showcase_local_admin')->ID);if(!current_user_can('manage_options'))exit(2);
$n=0;$files=array();$made=array();function check245($v,$m){global $n;if(!$v)throw new RuntimeException($m);$n++;}function nid245(){do{$s=(string)random_int(700000000,799999999);$v=0;for($i=0;$i<9;$i++)$v+=(int)$s[$i]*(10-$i);$r=$v%11;$s.=($r<2?$r:11-$r);}while(username_exists($s));return $s;}
function file245($rows){global $files;$b=dgs_school_xlsx($rows);if(is_wp_error($b))throw new RuntimeException($b->get_error_message());$p=wp_tempnam('teacher-test.xlsx');file_put_contents($p,$b);$files[]=$p;return $p;}
try{
$id=nid245();$minimal=array('national_id'=>$id,'full_name'=>'دبیر آزمایش');$d=dgs_teacher_validate($minimal);check245(!is_wp_error($d)&&$d['phone']===''&&$d['grades']===''&&$d['specialty']==='','optional fields blank');check245(is_wp_error(dgs_teacher_validate(array('national_id'=>$id,'full_name'=>''))),'name mandatory');check245(is_wp_error(dgs_teacher_validate(array('national_id'=>'123','full_name'=>'تست'))),'national checksum enforced');
foreach(array('09120000001','9120000001','۰۹۱۲۰۰۰۰۰۰۱') as $phone){$v=dgs_teacher_validate($minimal+array('phone'=>$phone));check245(!is_wp_error($v)&&$v['phone']==='09120000001','phone zero normalized');}
$v=dgs_teacher_validate($minimal+array('phone'=>'091200000001'));check245(is_wp_error($v)&&$v->get_error_code()==='phone','bad phone rejected');$v=dgs_teacher_validate($minimal+array('gender'=>'زن'));check245(!is_wp_error($v)&&$v['gender']==='female','Persian gender supported');
$cols=array_keys(dgs_teacher_fields());$row=array_map(function($k)use($d){return $d[$k];},$cols);$file=file245(array($cols,$row));$numbers=array();$rows=dgs_school_xlsx_rows($file,$cols,$numbers);check245(!is_wp_error($rows)&&$rows[0]===$row&&$numbers===array(2),'XLSX text roundtrip');
$z=new PclZip($file);$a=$z->extract(PCLZIP_OPT_BY_NAME,'xl/styles.xml',PCLZIP_OPT_EXTRACT_AS_STRING);check245(strpos($a[0]['content'],'numFmtId="49"')!==false,'explicit text style');$a=$z->extract(PCLZIP_OPT_BY_NAME,'xl/worksheets/sheet1.xml',PCLZIP_OPT_EXTRACT_AS_STRING);check245(strpos($a[0]['content'],'<col min="1" max="16384" style="1"/>')!==false,'empty future cells text formatted');
$partial=file245(array(array('full_name','national_id'),array('دبیر آزمایش',$id)));$rows=dgs_school_xlsx_rows($partial,$cols);check245(!is_wp_error($rows)&&$rows[0][0]===$id&&$rows[0][2]==='','optional columns may be absent/reordered');
// Reproduce LibreOffice prefixed XML that casts to false despite being valid.
$shared=wp_tempnam('sharedStrings.xml');$files[]=$shared;file_put_contents($shared,'<?xml version="1.0"?><x:sst xmlns:x="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><x:si><x:t>test</x:t></x:si></x:sst>');$z=new PclZip($partial);$z->add(array(array(PCLZIP_ATT_FILE_NAME=>$shared,PCLZIP_ATT_FILE_NEW_FULL_NAME=>'xl/sharedStrings.xml')));$rows=dgs_school_xlsx_rows($partial,$cols);check245(!is_wp_error($rows),'valid namespace-prefixed shared strings accepted');
$bad=$row;$bad[2]='bad';$r=dgs_teacher_import_rows(array($bad),array(12));check245(is_wp_error($r)&&strpos($r->get_error_message(),'12')!==false&&strpos($r->get_error_message(),'phone')!==false,'real row number and column in errors');check245(!username_exists($id),'invalid batch creates no accounts');
$r=dgs_teacher_import_rows(array($row));check245($r===1,'minimal teacher import succeeds');$uid=username_exists($id);$made[]=$uid;check245(get_user_meta($uid,'_dgs_contact_phone',true)==='','empty mobile remains empty');$r=dgs_teacher_import_rows(array($row));check245(is_wp_error($r),'existing accounts protected');
echo "PASS $n teacher XLSX regression checks\n";
}finally{require_once ABSPATH.'wp-admin/includes/user.php';foreach($made as $id){$post=get_user_meta($id,'_dgs_teacher_post',true);if($post)wp_delete_post($post,true);wp_delete_user($id);}foreach($files as $f)@unlink($f);}
